// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

// Package ar implements a minimal, defensive reader and writer for the common ar archive format
// (as used by Debian packages). Malformed archives result in errors, never panics.
package ar

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
	"time"
)

const (
	globalHeader = "!<arch>\n"
	headerSize   = 60
	headerEnd    = "`\n"
)

var (
	ErrInvalidHeader = errors.New("ar: invalid header")
	ErrWriteTooLong  = errors.New("ar: write too long")
)

// Header is the metadata of an archive member.
type Header struct {
	Name    string
	ModTime time.Time
	Uid     int
	Gid     int
	Mode    int64
	Size    int64
}

// Reader reads the members of an ar archive.
type Reader struct {
	r   io.Reader
	nb  int64
	pad int64
}

// NewReader creates a Reader and consumes the global archive header.
func NewReader(r io.Reader) *Reader {
	_, _ = io.CopyN(io.Discard, r, int64(len(globalHeader)))
	return &Reader{r: r}
}

func parseField(b []byte, base int) (int64, error) {
	s := strings.TrimSpace(string(b))
	if s == "" {
		return 0, nil
	}
	return strconv.ParseInt(s, base, 64)
}

// Next advances to the next member.
func (rd *Reader) Next() (*Header, error) {
	if skip := rd.nb + rd.pad; skip > 0 {
		rd.nb, rd.pad = 0, 0
		if _, err := io.CopyN(io.Discard, rd.r, skip); err != nil {
			return nil, err
		}
	}
	rd.nb, rd.pad = 0, 0

	buf := make([]byte, headerSize)
	if _, err := io.ReadFull(rd.r, buf); err != nil {
		return nil, err
	}
	if string(buf[58:60]) != headerEnd {
		return nil, ErrInvalidHeader
	}

	h := &Header{Name: strings.TrimRight(string(buf[0:16]), " ")}
	mod, err := parseField(buf[16:28], 10)
	if err != nil {
		return nil, fmt.Errorf("%w: mtime", ErrInvalidHeader)
	}
	h.ModTime = time.Unix(mod, 0)
	uid, err := parseField(buf[28:34], 10)
	if err != nil {
		return nil, fmt.Errorf("%w: uid", ErrInvalidHeader)
	}
	gid, err := parseField(buf[34:40], 10)
	if err != nil {
		return nil, fmt.Errorf("%w: gid", ErrInvalidHeader)
	}
	h.Uid, h.Gid = int(uid), int(gid)
	if h.Mode, err = parseField(buf[40:48], 8); err != nil {
		return nil, fmt.Errorf("%w: mode", ErrInvalidHeader)
	}
	if h.Size, err = parseField(buf[48:58], 10); err != nil || h.Size < 0 {
		return nil, fmt.Errorf("%w: size", ErrInvalidHeader)
	}

	rd.nb = h.Size
	rd.pad = h.Size % 2
	return h, nil
}

// Read reads from the current member.
func (rd *Reader) Read(b []byte) (int, error) {
	if rd.nb <= 0 {
		return 0, io.EOF
	}
	if int64(len(b)) > rd.nb {
		b = b[:rd.nb]
	}
	n, err := rd.r.Read(b)
	rd.nb -= int64(n)
	return n, err
}

// Writer writes an ar archive.
type Writer struct {
	w   io.Writer
	nb  int64
	pad bool
}

// NewWriter creates a Writer.
func NewWriter(w io.Writer) *Writer {
	return &Writer{w: w}
}

// WriteGlobalHeader writes the archive magic.
func (aw *Writer) WriteGlobalHeader() error {
	_, err := io.WriteString(aw.w, globalHeader)
	return err
}

// WriteHeader writes a member header.
func (aw *Writer) WriteHeader(h *Header) error {
	if aw.nb > 0 {
		return ErrWriteTooLong
	}
	if aw.pad {
		if _, err := aw.w.Write([]byte{'\n'}); err != nil {
			return err
		}
		aw.pad = false
	}
	if len(h.Name) > 16 || h.Size < 0 {
		return ErrInvalidHeader
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "%-16s%-12d%-6d%-6d%-8o%-10d%s", h.Name, h.ModTime.Unix(), h.Uid, h.Gid, h.Mode, h.Size, headerEnd)
	if _, err := aw.w.Write(b.Bytes()); err != nil {
		return err
	}
	aw.nb = h.Size
	aw.pad = h.Size%2 == 1
	return nil
}

// Write writes member data.
func (aw *Writer) Write(p []byte) (int, error) {
	if int64(len(p)) > aw.nb {
		return 0, ErrWriteTooLong
	}
	n, err := aw.w.Write(p)
	aw.nb -= int64(n)
	return n, err
}

