cat > modules/packages/ar/ar_test.go <<'EOF'
// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

package ar

import (
	"bytes"
	"io"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRoundTrip(t *testing.T) {
	var buf bytes.Buffer
	w := NewWriter(&buf)
	require.NoError(t, w.WriteGlobalHeader())
	for name, content := range map[string]string{"a": "odd", "b": "even"} {
		require.NoError(t, w.WriteHeader(&Header{Name: name, Mode: 0o600, Size: int64(len(content))}))
		_, err := w.Write([]byte(content))
		require.NoError(t, err)
	}

	r := NewReader(&buf)
	got := map[string]string{}
	for {
		h, err := r.Next()
		if err == io.EOF {
			break
		}
		require.NoError(t, err)
		b, err := io.ReadAll(r)
		require.NoError(t, err)
		assert.EqualValues(t, len(b), h.Size)
		got[h.Name] = string(b)
	}
	assert.Equal(t, map[string]string{"a": "odd", "b": "even"}, got)
}

func TestMalformed(t *testing.T) {
	hdr := func(size string) string {
		return "!<arch>\n" + "x               " + "0           0     0     644     " + size + "`\n"
	}
	for _, size := range []string{"-5        ", "abc       "} {
		r := NewReader(strings.NewReader(hdr(size)))
		assert.NotPanics(t, func() {
			_, err := r.Next()
			assert.Error(t, err)
		})
	}
	// short mode field must not panic
	r := NewReader(strings.NewReader("!<arch>\n" + strings.Repeat(" ", 48) + "5         `\n"))
	assert.NotPanics(t, func() { _, _ = r.Next() })
}
EOF
go mod tidy 2>&1 | tail -5; git diff go.mod; go build ./modules/... && go test ./modules/packages/ar ./modules/packages/debian 2>&1 | tail -20

